// Lazy per-locale script fallback fonts for the docs site.
//
// The bundled text families (Geist Sans/Mono, the OFL Studio fonts) carry
// Latin only. The web engine has its own global Noto fallback chain, but
// those faces are fetched from fonts.gstatic.com at render time, so any
// environment without Google-Fonts access (filtered networks, sandboxes,
// capture rigs) paints every non-Latin glyph as a .notdef tofu box.
//
// Fix: commit per-script Noto Sans subsets under assets/fonts/script/
// (generated by scripts/subset_script_fonts.py from the engine's own
// pinned fallback sources + css2 subsetting for the CJK families) and
// register them through FontLoader for the active locale — plus the
// [DocsNotoGlobal] subset, which covers the Latin-ext/Greek/Cyrillic
// code points of the Latin locales Geist misses. Registered fonts join
// the engine-wide TypefaceFontProvider used for glyph fallback, so this
// needs no TextStyle changes anywhere in the kit or docs.
//
// Bundles are lazy: the declared assets are only downloaded when a locale
// needs their script. No Material fonts are bundled (no Roboto).

import 'dart:ui' show Locale;

import 'package:flutter/services.dart';

import '../state/docs_strings.dart';

/// One script subset: the registered family name and its asset path.
class ScriptFontSpec {
  /// Creates a spec.
  const ScriptFontSpec(this.family, this.asset);

  /// Family name registered with the text engine (`DocsNoto…` names, all
  /// distinct from the bundled families and the engine's download list).
  final String family;

  /// Path of the committed subset (bundled via the pubspec `assets:` list;
  /// plain assets load lazily and are never parsed at boot).
  final String asset;
}

/// The per-script subsets, keyed by the language switcher's locale tags
/// (see [docsLocaleTag]). Mirrors `TAG_TO_FONT` in
/// `scripts/subset_script_fonts.py`; a test keeps the two in lockstep.
const Map<String, ScriptFontSpec> kDocsScriptFonts = <String, ScriptFontSpec>{
  'ar': ScriptFontSpec('DocsNotoArabic', 'assets/fonts/script/arabic.woff2'),
  'fa': ScriptFontSpec('DocsNotoArabic', 'assets/fonts/script/arabic.woff2'),
  'ps': ScriptFontSpec('DocsNotoArabic', 'assets/fonts/script/arabic.woff2'),
  'ur': ScriptFontSpec('DocsNotoArabic', 'assets/fonts/script/arabic.woff2'),
  'he': ScriptFontSpec('DocsNotoHebrew', 'assets/fonts/script/hebrew.woff2'),
  'hi': ScriptFontSpec(
    'DocsNotoDevanagari',
    'assets/fonts/script/devanagari.woff2',
  ),
  'mr': ScriptFontSpec(
    'DocsNotoDevanagari',
    'assets/fonts/script/devanagari.woff2',
  ),
  'bn': ScriptFontSpec('DocsNotoBengali', 'assets/fonts/script/bengali.woff2'),
  'ta': ScriptFontSpec('DocsNotoTamil', 'assets/fonts/script/tamil.woff2'),
  'te': ScriptFontSpec('DocsNotoTelugu', 'assets/fonts/script/telugu.woff2'),
  'th': ScriptFontSpec('DocsNotoThai', 'assets/fonts/script/thai.woff2'),
  'ko': ScriptFontSpec('DocsNotoHangul', 'assets/fonts/script/korean.woff2'),
  'ja': ScriptFontSpec(
    'DocsNotoJapanese',
    'assets/fonts/script/japanese.woff2',
  ),
  'zh': ScriptFontSpec(
    'DocsNotoSimplifiedChinese',
    'assets/fonts/script/chinese-sc.woff2',
  ),
  'zh_Hans': ScriptFontSpec(
    'DocsNotoSimplifiedChinese',
    'assets/fonts/script/chinese-sc.woff2',
  ),
  'zh_Hant': ScriptFontSpec(
    'DocsNotoTraditionalChinese',
    'assets/fonts/script/chinese-tc.woff2',
  ),
};

/// The global subset: Latin-leftover coverage for every locale (Greek,
/// Cyrillic, Vietnamese, Latin-ext and the typographic punctuation the
/// bundled Geist cuts miss). Loaded at startup on every visit.
const ScriptFontSpec kDocsGlobalScriptFont = ScriptFontSpec(
  'DocsNotoGlobal',
  'assets/fonts/script/global.woff2',
);

/// The script fallback chain, in family order, appended to the default
/// `ThemeSans` / `GeistMono` stacks in `ThemeDocument.theme` so every text
/// style can resolve the glyphs of any offered script when its subset is
/// loaded (Skia skips the unregistered ones and re-lays text via the
/// engine's fontsChange message once a FontLoader registration lands).
///
/// `NotoSansSymbols2` stays last: bundled symbol coverage before the
/// engine's own remote chain (which still applies when online).
const String kDocsScriptFallbackStack =
    'DocsNotoArabic, DocsNotoHebrew, DocsNotoDevanagari, DocsNotoBengali,'
    ' DocsNotoTamil, DocsNotoTelugu, DocsNotoThai, DocsNotoHangul,'
    ' DocsNotoJapanese, DocsNotoSimplifiedChinese,'
    ' DocsNotoTraditionalChinese, DocsNotoGlobal, NotoSansSymbols2';

/// Default `fontSans` spec (`ThemeDocument.theme` default): the bundled
/// default family with every script subset behind it.
const String kDocsDefaultBodyFontStack = 'GeistSans, $kDocsScriptFallbackStack';

/// Default `fontMono` spec: same idea for code blocks and `inlineCode`.
const String kDocsDefaultMonoFontStack = 'GeistMono, $kDocsScriptFallbackStack';

/// The subset family for [locale], or null when the bundled families cover
/// it and the engine's global fallback chain is the right answer.
ScriptFontSpec? docsScriptFontFor(Locale locale) {
  return kDocsScriptFonts[docsLocaleTag(locale)];
}

final Set<String> _loadedFamilies = <String>{};

/// Whether [family] has been registered this session.
bool docsScriptFontLoaded(String family) => _loadedFamilies.contains(family);

/// Registers every subset in [families] with the text engine (FontLoader).
///
/// Failures never break the site: an unregistered family keeps the engine's
/// global Noto fallback (same behaviour as before on a healthy network).
/// Idempotent per family.
Future<void> loadDocsScriptFonts(Iterable<String> tags) async {
  final Map<String, String> pending = <String, String>{
    kDocsGlobalScriptFont.asset: kDocsGlobalScriptFont.family,
  };
  for (final String tag in tags) {
    final ScriptFontSpec? spec = kDocsScriptFonts[tag];
    if (spec != null) {
      pending[spec.asset] = spec.family;
    }
  }
  for (final MapEntry<String, String> entry in pending.entries) {
    final String asset = entry.key;
    final String family = entry.value;
    if (_loadedFamilies.contains(family)) {
      continue;
    }
    try {
      final FontLoader loader = FontLoader(family);
      loader.addFont(rootBundle.load(asset));
      await loader.load();
      _loadedFamilies.add(family);
    } on Object {
      // Offline or a missing build asset: keep the engine's global fallback
      // rather than break boot.
    }
  }
}

/// Convenience: the subsets for [locale] (never skips the global subset).
Future<void> loadDocsScriptFont(Locale locale) {
  return loadDocsScriptFonts(<String>[docsLocaleTag(locale)]);
}
